    $cc = strtolower($cc); $n = esc_attr($name);
    if (isset($SVG[$cc])) return ' <img class="ath-flag" src="data:image/svg+xml;base64,' . base64_encode($SVG[$cc]) . '" alt="' . $n . '" title="' . $n . '" width="14" height="14">';
