    if (in_array($cc, ['gb-eng', 'gb-sct', 'gb-wls'], true)) {   // England, Scotland, Wales: the emoji tag flags
        $f = mb_chr(0x1F3F4, 'UTF-8'); foreach (str_split(str_replace('-', '', $cc)) as $ch) $f .= mb_chr(0xE0000 + ord($ch), 'UTF-8'); $f .= mb_chr(0xE007F, 'UTF-8');
