        if ($st[2] !== 'both' && $st[2] !== $kind) continue;
        foreach ($st[3] as $pn) {
            if (($pn[0] ?? '') !== 'p' || (isset($pn['only']) && $pn['only'] !== $kind)) continue;
            $rows = '';
            foreach ($pn['fields'] as $f) {
                if (!array_key_exists($f[0], $a)) continue; $v = cc_f_val($f, $a[$f[0]]); if ($v === '') continue;
