    function __construct() { $this->page(); }
    private function page() { if ($this->s !== '') $this->pages[] = $this->s; $this->s = ''; $this->y = self::H - self::M; }
    private static function enc($t) { $t = str_replace(['’', '‘', '“', '”', '–', '—', '…', '→'], ["'", "'", '"', '"', '-', '-', '...', '->'], $t);
